public class WarehouseSinkTask extends SinkTask {
    private static final Logger log = LoggerFactory.getLogger(WarehouseSinkTask.class);
    private final List<Row> buffer = new ArrayList<>();
    private WarehouseClient client;   // our HTTP client for the bulk API

    @Override public String version() { return "1.4.0"; }

    @Override public void start(Map<String, String> props) {
        client = WarehouseClient.connect(props.get("warehouse.url"), props.get("warehouse.token"));
    }

    @Override public void put(Collection<SinkRecord> records) {
        for (SinkRecord r : records) {
            try {
                buffer.add(Row.from(r.value()));
            } catch (Exception e) {
                log.warn("skipping bad record {}-{}@{}", r.topic(), r.kafkaPartition(), r.kafkaOffset(), e);
            }
        }
        if (buffer.size() >= 5000) {
            client.bulkInsertAsync(new ArrayList<>(buffer));   // returns CompletableFuture<Void>, not awaited
            buffer.clear();
        }
    }

    @Override public void stop() { client.close(); }
}

