public static void main(String[] args) throws Exception {
    Set<Integer> ids = Arrays.stream(args).map(Integer::valueOf).collect(Collectors.toSet());
    try (Admin admin = Admin.create(loadProps("/etc/ci-gate/client.properties"))) {
        Set<String> topics = admin.listTopics().names().get();
        Map<String, TopicDescription> desc = admin.describeTopics(topics).allTopicNames().get();
        for (TopicDescription td : desc.values()) {
            for (TopicPartitionInfo p : td.partitions()) {
                if (p.leader() != null && ids.contains(p.leader().id())) {
                    System.err.println("leader on " + p.leader().id() + ": " + td.name() + "-" + p.partition());
                    System.exit(1);
                }
            }
        }
    }
    System.out.println("OK");
}

